-- 002_import_all_envelope_parties.sql
-- Populates all 1,836 MARG ERP parties into B2B PostgreSQL database
-- Includes live GPS coordinates, route, contact, and GSTIN for map & nearest chemist radar

ON CONFLICT (party_code) DO UPDATE SET
  party_name = EXCLUDED.party_name,
  mobile = EXCLUDED.mobile,
  email = EXCLUDED.email,
  gst_number = EXCLUDED.gst_number,
  address = EXCLUDED.address,
  state = EXCLUDED.state,
  city = EXCLUDED.city,
  area = EXCLUDED.area,
  delivery_route = EXCLUDED.delivery_route,
  latitude = EXCLUDED.latitude,
  longitude = EXCLUDED.longitude,
  status = EXCLUDED.status;
